/**
 * Unit tests for org.apache.commons.lang.BooleanUtils.isFalse(Boolean bool)
 */
public class BooleanUtils_isFalse_TriageGen1Test {



    @Test
    public void testIsFalse_withTrue() {
        // Covers: return bool.booleanValue() ? false : true; (True branch)
        Boolean input = Boolean.TRUE;
        boolean expected = false;
        boolean actual = BooleanUtils.isFalse(input);
        assertEquals("isFalse(true) should return false", expected, actual);
    }


}

package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.math.NumberUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.BooleanUtils.isFalse(Boolean bool)
 */
public class BooleanUtils_isFalse_TriageGen1Test {





    @Test
    public void testIsFalse_withFalse() {
        // Covers: return bool.booleanValue() ? false : true; (False branch)
        Boolean input = Boolean.FALSE;
        boolean expected = true;
        boolean actual = BooleanUtils.isFalse(input);
        assertEquals("isFalse(false) should return true", expected, actual);
    }
}
